//一次向TLC5615中写入12bit数据函数
void Write_12Bits(void) {
uchar i;
SCL=0; //置零SCL，为写bit做准备；
CS=0; //片选端 =0；
for(i=0;i<2;i++) { //循环2次，发送高两位；
if(h_7) { //高位先发；
DIN = 1; //将数据送出；
SCL = 1; //提升时钟，写操作在时钟上升沿触发
SCL = 0; //结束该位传送，为下次写作准备；
} else{ DIN= 0;
SCL = 1;
CL = 0;
} dat_in_h <<= 1;
}

