}
}
void delay18us(void) { //延时约18µs函数
_nop_();_nop_();_nop_();_nop_();_nop_();_nop_();_nop_();_nop_();_no
p_();_nop_();_nop_();_nop_();_nop_();_nop_();_nop_();_nop_(); 
nop_();_nop_();
}

11.5.2 案例设计：单片机扩展TLC549的设计
uchar convert(void) {
uchar i,temp;
cs=0;
delay18us();
for(i=0;i<8;i++) {
if(sdo==1)temp=temp|0x01;
if(i<7)temp=temp<<1;
sclk=1;
_nop_(); _nop_(); _nop_();_nop_(); 
sclk=0;
_nop_(); _nop_();
}
cs=1;
return(temp);
}

