sbit DATOUT=P1^0; //定义P1.0与DATA OUT相连
sbit DATIN=P1^1; //定义P1.1与DATA INPUT相连
sbit CS=P1^2; //定义P1.2与 端相连
sbit IOCLK=P1^3; //定义P1.3与I/O CLOCK相连
sbit EOC=P1^4; //定义P1.4与EOC引脚相连
