11.6.2 案例设计：单片机扩展TLC2543的设计
void delay_ms(unit i) {
int j;
for(; i>0; i--)
for(j=0; j<123; j++);
}
unit getdata(uchar channel) { // getdata()为获取转换结果函数，
//channel 为通道号
uchar i,temp;
unit read_ad_data=0; // 分别存放采集的数据，先清0
channel=channel<<4; // 结果为12位数据格式，
//高位导前，单极性××××0000
IOCLK=0;
CS=0; // 下跳沿，并保持低电平
temp=channel; // 输入要转换的通道

11.6.2 案例设计：单片机扩展TLC2543的设计
for(i=0;i<12;i++) { 
if(DATOUT) read_ad_data=read_ad_data|0x01;
//读入转换结果
DATIN=(bit)(temp&0x80); //写入方式/通道命令字
IOCLK=1; //IOCLK上跳沿
_nop_();_nop_();_nop_(); //空操作延时
IOCLK=0;
_nop_();_nop_();_nop_();
temp=temp<<1; //左移1位，准备发送
//方式通道控制字下一位
read_ad_data<<=1; //转换结果左移1位
}
CS=1; // CS上跳沿
read_ad_data>>=1; // 抵消第12次左移，得到12位转换结果
return(read_ad_data); }

